":\"A binary value, multibase base58btc over the suite's canonical (compressed) encoding.\",\"type\":\"string\",\"maxLength\":16384,\"pattern\":\"^z[1-9A-HJ-NP-Za-km-z]+$\"},\"Cast\":{\"title\":\"Cast\",\"description\":\"A ballot and the PCS attestation that admits it (VTI-VOT-030). `attestation` is the suite's canonical encoding of the attestation made for the election point with the ballot context bound in (CONVENTIONS §3); `tag` repeats its tag so a ballot box can refuse a duplicate before the pairing check.\",\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"ballot\",\"tag\",\"attestation\"],\"properties\":{\"ballot\":{\"$ref\":\"#/$defs/Ballot\"},\"tag\":{\"$ref\":\"#/$defs/Multibase\"},\"attestation\":{\"$ref\":\"#/$defs/Multibase\"}}},\"Ballot\":{\"title\":\"Ballot\",\"description\":\"An open ballot: one answer per question of the manifest, in any order. The bytes a cast's proof binds are the RFC 8785 (JCS) canonicalization of this object as received.\",\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"electionId\",\"manifestDigest\",\"answers\"],\"properties\":{\"electionId\":{\"$ref\":\"#/$defs/ElectionId\"},\"manifestDigest\":{\"$ref\":\"#/$defs/DigestMultibase\"},\"answers\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":128,\"items\":{\"$ref\":\"#/$defs/Answer\"}}}},\"Answer\":{\"title\":\"Answer\",\"description\":\"The answer to one question. Exactly one member besides `question` is present, matching the question's type, or `abstain` for an optional question left unanswered.\",\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"question\"],\"minProperties\":2,\"maxProperties\":2,\"properties\":{\"question\":{\"$ref\":\"#/$defs/Key\"},\"choice\":{\"type\":\"array\",\"items\":{\"$ref\":\"#/$defs/Key\"},\"uniqueItems\":true},\"ranking\":{\"type\":\"array\",\"items\":{\"$ref\":\"#/$defs/Key\"},\"uniqueItems\":true},\"scores\":{\"type\":\"object\",\"propertyNames\":{\"$ref\":\"#/$defs/Key\"},\"additionalProperties\":{\"type\":\"integer\"}},\"text\":{\"type\":\"string\",\"maxLength\":4096},\"abstain\":{\"const\":true}}}}}"

// Spec is the SPEC §7.2 policy for the request variant, taken from this
// specification's front matter. Pass it to trusttasks.ConsumeInbound — items 5b,
// 7 and 8 are per-specification and cannot be derived from the document alone,
// and item 2 needs the schema it carries.
var Spec = trusttasks.SpecPolicy{
	TypeURI:             TypeURI,
	IsBearer:            false,
	IsProofRequired:     false,
	IsRecipientRequired: true,
	IsIssuedAtRequired:  false,
	PayloadSchema:       PayloadSchemaJSON,
}

// ResponseSpec is the SPEC §7.2 policy for the success-response variant.
// IsRecipientRequired tracks the *issuer* party's requirement, because a response
// swaps the parties (§7.3 item 5).
var ResponseSpec = trusttasks.SpecPolicy{
	TypeURI:             ResponseTypeURI,
	IsBearer:            false,
	IsProofRequired:     false,
	IsRecipientRequired: false,
	IsIssuedAtRequired:  false,
	PayloadSchema:       ResponsePayloadSchemaJSON,
}
